public static class RiftTalentPresentation {
 static readonly string[] IconAbilityIds={"CleavingFury","cleaving-sweep","cleaving-sweep","last-stand","HonoredRoar","last-stand","CleavingFury","Earthbreaker","whirling-execution"};
 public static Sprite Icon(AbilityController combat,int index){if(!combat||index<0||index>=IconAbilityIds.Length)return null;int id=combat.AbilityIndex(IconAbilityIds[index]);var a=id>0?combat.Definition(id):null;return a?a.Icon:null;}
 public static string Effect(int index,int rank){switch(index){case 0:return "+"+(3*rank)+"% de daño";case 1:return "+"+(15*rank)+"° de arco y +"+(.3f*rank).ToString("0.#")+" m en Furia/Barrido";case 2:return "+"+rank+"% de crítico y +"+(5*rank)+"% de daño de Barrido";case 3:return "+"+(2*rank)+"% de reducción de daño";case 4:return "+"+(5*rank)+"% de vida máxima";case 5:return "Con escudo: +"+(3*rank)+"% de reducción y -"+(5*rank)+"% de recarga de Última resistencia";case 6:return "+"+(10*rank)+"% de generación de Furia";case 7:return "Rompetierra: +"+(8*rank)+"% de daño y +"+(.1f*rank).ToString("0.#")+" s de stagger";case 8:return "-"+(3*rank)+"% de recarga de habilidades";default:return "Consultar definición de talento";}}
}
public sealed class RiftTalentLink:MonoBehaviour {
 public int ParentIndex,ChildIndex;public Vector2 LineStart,LineEnd;public Image Segment;
 public Color color {get=>Segment?Segment.color:Color.clear;set{if(Segment)Segment.color=value;}}
 public void Build(){var go=new GameObject("Dependency stroke",typeof(RectTransform),typeof(Image));go.transform.SetParent(transform,false);Segment=go.GetComponent<Image>();Segment.raycastTarget=false;var rect=Segment.rectTransform;rect.anchorMin=rect.anchorMax=new Vector2(0,1);rect.pivot=new Vector2(.5f,.5f);rect.anchoredPosition=(LineStart+LineEnd)*.5f;var delta=LineEnd-LineStart;rect.sizeDelta=new Vector2(delta.magnitude,3);rect.localRotation=Quaternion.Euler(0,0,Mathf.Atan2(delta.y,delta.x)*Mathf.Rad2Deg);}
 public void SetVerticesDirty(){if(Segment)Segment.SetVerticesDirty();}
}
public sealed class RiftTalentTreeView:MonoBehaviour {
 PlayerInstance player;AbilityController combat;RiftHub hub;WarriorProgressionDefinition tuning;Text summary;float next;
 RectTransform graph;ScrollRect navigator;Vector2[] points;float zoom=.65f,viewWidth=676;bool pilot;int selected;RiftTalentDetailCard detailCard;
 public int SelectedIndex=>selected;public float ViewWidth=>viewWidth;
 public float Zoom=>zoom;readonly System.Collections.Generic.List<RiftTalentNodeView> nodes=new System.Collections.Generic.List<RiftTalentNodeView>();readonly System.Collections.Generic.List<RiftTalentLink> links=new System.Collections.Generic.List<RiftTalentLink>();
 public bool Available(int index){var n=tuning.Talents[index];return combat&&combat.Prototype&&combat.CanChangeBuild&&combat.TalentPoints>0&&combat.Level>=n.RequiredLevel&&combat.Rank(index)<n.MaximumRank&&(n.Parent<0||combat.Rank(n.Parent)>=tuning.Talents[n.Parent].MaximumRank);}
 public string BlockReason(int index){var n=tuning.Talents[index];if(combat.Rank(index)>=n.MaximumRank)return "Rango máximo";if(combat.Level<n.RequiredLevel)return "Requiere nivel "+n.RequiredLevel;if(n.Parent>=0&&combat.Rank(n.Parent)<tuning.Talents[n.Parent].MaximumRank)return "Requiere "+tuning.Talents[n.Parent].Name+" "+tuning.Talents[n.Parent].MaximumRank+"/"+tuning.Talents[n.Parent].MaximumRank;if(combat.TalentPoints<=0)return "Sin puntos disponibles";if(!combat.CanChangeBuild)return "Refugio o fuera de combate; no durante una habilidad";return "Disponible · 1 punto";}
 public void Build(PlayerInstance owner,AbilityController abilities,RiftHub menu){player=owner;combat=abilities;hub=menu;tuning=combat.Progression;var body=(RectTransform)transform;pilot=body.rect.width>1000;viewWidth=pilot?900:676;
  if(pilot){var strip=RiftSkillStyle.Panel(body,"Summary backing",0,0,viewWidth,104,.3f);detailCard=RiftTalentDetailCard.Create(body,930,this);}
  RiftWidgets.Label(body,"TALENTOS",12,0,viewWidth-24,32,28,RiftSkillStyle.White);summary=RiftWidgets.Label(body,"",12,34,viewWidth-24,30,20,pilot?new Color(.94f,.8f,.55f):RiftWidgets.Gold);
  var viewportRoot=RiftWidgets.Rect(body,"Talent navigator",0,112,viewWidth,520);navigator=viewportRoot.gameObject.AddComponent<ScrollRect>();navigator.horizontal=navigator.vertical=true;navigator.movementType=ScrollRect.MovementType.Clamped;navigator.inertia=false;navigator.scrollSensitivity=0;
  var viewport=RiftWidgets.Rect(viewportRoot,"Viewport",0,0,viewWidth,520);viewport.gameObject.AddComponent<RectMask2D>();var hit=viewport.gameObject.AddComponent<Image>();hit.color=new Color(.033f,.036f,.055f,pilot?.12f:.75f);hit.raycastTarget=true;navigator.viewport=viewport;viewport.gameObject.AddComponent<RiftTalentGraphInput>().Tree=this;
  graph=RiftWidgets.Rect(viewport,"Talent graph",0,0,1400,1120);navigator.content=graph;
  
  var branches=tuning.Talents.Select(t=>t.Branch).Distinct().ToArray();points=new Vector2[tuning.Talents.Length];int[] rows=new int[branches.Length];var center=new Vector2(700,460);float[] angles={145,35,-90};for(int i=0;i<points.Length;i++){int col=Array.IndexOf(branches,tuning.Talents[i].Branch);float angle=angles[col]*Mathf.Deg2Rad;var branch=col==0?new[]{new Vector2(530,550),new Vector2(340,310),new Vector2(150,70)}:col==1?new[]{new Vector2(870,550),new Vector2(1060,310),new Vector2(1250,70)}:new[]{new Vector2(700,780),new Vector2(970,950),new Vector2(1240,780)};points[i]=branch[rows[col]++];}
  for(int i=0;i<points.Length;i++){int parent=tuning.Talents[i].Parent;if(parent<0){var direction=(points[i]-center).normalized;float distance=Vector2.Distance(center,points[i]);for(float d=90;d<distance-65;d+=25){var dash=RiftWidgets.Rect(graph,"Branch guide",0,0,1400,1120).gameObject.AddComponent<RiftTalentLink>();dash.LineStart=new Vector2(center.x+direction.x*d,-center.y-direction.y*d);dash.LineEnd=new Vector2(center.x+direction.x*Mathf.Min(d+12,distance-65),-center.y-direction.y*Mathf.Min(d+12,distance-65));dash.Build();dash.color=new Color(.4f,.35f,.26f,.55f);Destroy(dash);}
   if(pilot)RiftWidgets.Image(graph,"Branch caption backing",points[i].x-100,points[i].y-145,200,35,new Color(.028f,.03f,.045f,.8f));
   var label=RiftWidgets.Label(graph,tuning.Talents[i].Branch.ToUpperInvariant(),points[i].x-100,points[i].y-145,200,35,26,pilot?new Color(.94f,.8f,.55f):RiftWidgets.Gold);label.alignment=TextAnchor.MiddleCenter;continue;}if(parent>=points.Length)continue;
   var delta=(points[i]-points[parent]).normalized;var start=points[parent]+delta*88;var end=points[i]-delta*88;var root=RiftWidgets.Rect(graph,"Dependency "+parent+" to "+i,0,0,1400,1120);var link=root.gameObject.AddComponent<RiftTalentLink>();link.ParentIndex=parent;link.ChildIndex=i;link.LineStart=new Vector2(start.x,-start.y);link.LineEnd=new Vector2(end.x,-end.y);link.Build();links.Add(link);
  }
  var core=RiftWidgets.Rect(graph,"Warrior origin",center.x-75,center.y-75,150,150);var coreGraphic=core.gameObject.AddComponent<RiftHUDGraphic>();coreGraphic.Shape=HUDShape.Diamond;coreGraphic.color=new Color(.14f,.07f,.24f,.86f);coreGraphic.Border=RiftSkillStyle.Violet;coreGraphic.raycastTarget=true;var hud=UnityEngine.Object.FindFirstObjectByType<RiftGameplayHUD>();RiftWidgets.Image(core,"Warrior portrait",43,35,64,64,Color.white,hud&&hud.Portrait?hud.Portrait.sprite:null);if(pilot)RiftWidgets.Image(core,"Origin caption backing",0,104,150,34,new Color(.035f,.03f,.025f,.88f));var coreLabel=RiftWidgets.Label(core,"WARRIOR",0,105,150,32,24,RiftWidgets.White);coreLabel.alignment=TextAnchor.MiddleCenter;var coreTip=core.gameObject.AddComponent<RiftTooltipTrigger>();coreTip.Title="Ramas de Warrior";coreTip.Description="Armas, Protección y Furia son ramas independientes. Las guías punteadas agrupan las ramas; no agregan requisitos. Las rutas continuas muestran los requisitos reales de cada talento.";
  for(int i=0;i<points.Length;i++){int index=i;var definition=tuning.Talents[i];var point=points[i];var root=RiftSkillStyle.Panel(graph,"Talent node "+i,point.x-80,point.y-80,160,160,.72f);root.GetComponent<RiftMapSurface>().Border=new Color(.8f,.48f,.2f);var button=root.gameObject.AddComponent<Button>();button.targetGraphic=root.GetComponent<RiftMapSurface>();button.onClick.AddListener(()=>{SelectNode(index);if(Available(index))player.GetComponent<RiftJournalPlayer>().CmdTalent(index);else hub.Notify(BlockReason(index));});
   var icon=RiftWidgets.Image(root,"Talent icon",8,8,144,144,Color.white,RiftTalentPresentation.Icon(combat,i));var badge=RiftWidgets.Image(root,"Rank background",0,132,160,28,new Color(.03f,.027f,.022f,.96f));var rank=RiftWidgets.Label(root,"",0,130,160,32,29,RiftWidgets.White);rank.alignment=TextAnchor.MiddleCenter;
   var pips=new Image[definition.MaximumRank];float width=definition.MaximumRank*20-3;for(int p=0;p<pips.Length;p++)pips[p]=RiftWidgets.Image(graph,"Rank pip",point.x-width/2+p*20,point.y+88,17,5,RiftWidgets.Muted);
   var backing=RiftWidgets.Image(graph,"Talent caption background",point.x-150,point.y+100,300,46,new Color(.028f,.03f,.045f,.88f));var title=RiftWidgets.Label(backing.transform,definition.Name,1,0,298,46,30,RiftWidgets.White);title.alignment=TextAnchor.MiddleCenter;
   var node=root.gameObject.AddComponent<RiftTalentNodeView>();node.Index=i;node.Tree=this;node.RankLabel=rank;node.Icon=icon;node.Pips=pips;node.Edge=root.gameObject.AddComponent<Outline>();node.Edge.effectDistance=new Vector2(2,-2);node.Tooltip=root.gameObject.AddComponent<RiftTooltipTrigger>();nodes.Add(node);
  }
  if(pilot)RiftWidgets.Image(body,"Legend backing",0,638,viewWidth,32,new Color(.025f,.028f,.046f,.7f));
  RiftWidgets.Label(body,"Rutas continuas: requisitos · Guías punteadas: ramas independientes",0,642,viewWidth,26,16,RiftWidgets.Muted);
  RiftWidgets.Label(body,"Arrastrá para mover · Rueda: zoom",12,74,viewWidth-340,30,17,RiftWidgets.Muted);
  MiniButton(body,"−",viewWidth-330,50,()=>SetZoom(zoom/1.2f));MiniButton(body,"+",viewWidth-272,50,()=>SetZoom(zoom*1.2f));MiniButton(body,"CENTRAR",viewWidth-214,100,()=>ResetView(false));MiniButton(body,"VER TODO",viewWidth-106,106,()=>ResetView(true));ResetView(true);
  RiftSkillStyle.Button(body,"REINICIAR · GRATIS",0,694,viewWidth*.51f,44,()=>hub.Dialog("Reiniciar talentos","Se devolverán todos los puntos gastados.",()=>player.GetComponent<RiftJournalPlayer>().CmdResetTalents()));RiftSkillStyle.Button(body,"LIBRO DE HABILIDADES",viewWidth*.54f,694,viewWidth*.46f,44,hub.ShowSkills);Refresh();
 }
 void MiniButton(Transform body,string label,float x,float width,Action clicked){var b=RiftSkillStyle.Button(body,label,x,74,width,30,clicked);var text=b.GetComponentInChildren<Text>();text.rectTransform.anchoredPosition=Vector2.zero;text.rectTransform.sizeDelta=new Vector2(width,30);text.alignment=TextAnchor.MiddleCenter;text.fontSize=17;}
 public void SetZoom(float value){var point=RectTransformUtility.WorldToScreenPoint(null,navigator.viewport.TransformPoint(navigator.viewport.rect.center));SetZoom(value,point);}
 public void SetZoom(float value,Vector2 screenPoint){RectTransformUtility.ScreenPointToLocalPointInRectangle(navigator.viewport,screenPoint,null,out var local);var world=navigator.viewport.TransformPoint(local);var focus=graph.InverseTransformPoint(world);zoom=Mathf.Clamp(value,.3f,1.3f);graph.localScale=Vector3.one*zoom;var correction=navigator.viewport.InverseTransformVector(world-graph.TransformPoint(focus));graph.anchoredPosition+=(Vector2)correction;}
 public void ResetView(bool all){zoom=all?.46f:.58f;graph.localScale=Vector3.one*zoom;var center=all?new Vector2(700,543):new Vector2(700,460);graph.anchoredPosition=new Vector2(viewWidth*.5f-center.x*zoom,center.y*zoom-navigator.viewport.rect.height*.5f);}
 public void CenterNode(int index){if(points==null||index<0||index>=points.Length)return;graph.anchoredPosition=new Vector2(viewWidth*.5f-points[index].x*zoom,points[index].y*zoom-navigator.viewport.rect.height*.5f);}
 public void SelectNode(int index){if(index<0||index>=tuning.Talents.Length)return;selected=index;Refresh();}
 public void LearnSelected(){if(Available(selected))player.GetComponent<RiftJournalPlayer>().CmdTalent(selected);else hub.Notify(BlockReason(selected));}
 void Update(){if(Time.unscaledTime>=next){next=Time.unscaledTime+.15f;Refresh();}}
 void Refresh(){if(!combat||!summary)return;summary.text="NIVEL "+combat.Level+"   ·   "+combat.TalentPoints+" PUNTOS DISPONIBLES";foreach(var node in nodes){var t=tuning.Talents[node.Index];int rank=combat.Rank(node.Index);bool available=Available(node.Index);var tint=rank>0?new Color(.95f,.75f,.42f):available?new Color(.78f,.59f,.32f):new Color(.28f,.27f,.24f);node.RankLabel.text=rank+" / "+t.MaximumRank;node.RankLabel.color=rank>0?RiftWidgets.White:RiftWidgets.Muted;node.Edge.effectColor=tint;var surface=node.GetComponent<RiftMapSurface>();surface.Border=node.Index==selected?RiftSkillStyle.Violet:tint;surface.Glow=node.Index==selected?4:rank>0?2:0;surface.SetVerticesDirty();node.Icon.color=rank>0||available?Color.white:new Color(.35f,.34f,.31f);for(int p=0;p<node.Pips.Length;p++)node.Pips[p].color=p<rank?new Color(.95f,.75f,.42f):new Color(.2f,.19f,.16f);
   string requirement=t.Parent<0?"Raíz de rama":tuning.Talents[t.Parent].Name+" "+tuning.Talents[t.Parent].MaximumRank+"/"+tuning.Talents[t.Parent].MaximumRank;
   node.Tooltip.Title=t.Name;node.Tooltip.Description="Rango "+rank+" / "+t.MaximumRank+"\nActual: "+RiftTalentPresentation.Effect(node.Index,rank)+"\nSiguiente: "+(rank>=t.MaximumRank?"Rango máximo":RiftTalentPresentation.Effect(node.Index,rank+1))+"\n\nCosto: "+(rank>=t.MaximumRank?"—":"1 punto")+"\nNivel requerido: "+t.RequiredLevel+"\nRequisitos: "+requirement+"\nEstado: "+(rank>=t.MaximumRank?"Completo":available?"Disponible":BlockReason(node.Index).StartsWith("Requiere")?"Bloqueado":BlockReason(node.Index));}
  if(detailCard)detailCard.Show(tuning.Talents[selected],selected,combat.Rank(selected),Available(selected),BlockReason(selected),tuning);
  foreach(var link in links){bool invested=combat.Rank(link.ChildIndex)>0;bool unlocked=combat.Rank(link.ParentIndex)>=tuning.Talents[link.ParentIndex].MaximumRank;link.color=invested?new Color(.8f,.32f,.13f):unlocked?new Color(.62f,.47f,.25f):new Color(.28f,.26f,.22f);var size=link.Segment.rectTransform.sizeDelta;link.Segment.rectTransform.sizeDelta=new Vector2(size.x,invested?7:unlocked?5:3);link.SetVerticesDirty();}
 }
}
public sealed class RiftTalentGraphInput:MonoBehaviour,IScrollHandler {public RiftTalentTreeView Tree;public void OnScroll(PointerEventData e){Tree.SetZoom(Tree.Zoom*Mathf.Pow(1.18f,e.scrollDelta.y),e.position);e.Use();}}
public sealed class RiftTalentNodeView:MonoBehaviour,ISelectHandler,IPointerEnterHandler {public RiftTalentTreeView Tree;public void OnPointerEnter(PointerEventData e){Tree.SelectNode(Index);}
 public void OnSelect(BaseEventData e){Tree.SelectNode(Index);if(!(e is PointerEventData))Tree.CenterNode(Index);}public int Index;public Text RankLabel;public Image Icon;public Image[] Pips;public Outline Edge;public RiftTooltipTrigger Tooltip;}
}
